Add-Type -TypeDefinition @'
using System; using System.Runtime.InteropServices; public class SessionObservation { [StructLayout(LayoutKind.Sequential)] public struct LASTINPUTINFO { public uint cbSize; public uint dwTime; } [DllImport("user32.dll")] public static extern bool GetLastInputInfo(ref LASTINPUTINFO p); [DllImport("kernel32.dll")] public static extern uint GetTickCount(); [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow(); [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint p); }
'@
$x=New-Object SessionObservation+LASTINPUTINFO; $x.cbSize=8; $ok=[SessionObservation]::GetLastInputInfo([ref]$x); [uint32]$pid2=0; $h=[SessionObservation]::GetForegroundWindow(); [void][SessionObservation]::GetWindowThreadProcessId($h,[ref]$pid2); @{inputRead=$ok;idleMs=(([long][SessionObservation]::GetTickCount()-[long]$x.dwTime+4294967296)%4294967296);foregroundPid=$pid2;foregroundProcess=(Get-Process -Id $pid2 -ErrorAction SilentlyContinue).ProcessName;inputSent=$false;observedAt=(Get-Date -Format o)} | ConvertTo-Json
